import { Eye, EyeOff, Search, X } from 'lucide-react'
import React, {
  useId,
  useRef,
  useState,
  type InputHTMLAttributes,
  type SelectHTMLAttributes,
  type TextareaHTMLAttributes,
} from 'react'
import { IconButton } from '@/components/common'
import { cn } from '@/lib/utils/cn'

const fieldStyles =
  'w-full rounded-md border border-[var(--border)] bg-white px-3 py-2 text-sm outline-none focus:border-[var(--focus)] focus:ring-2 focus:ring-[var(--focus)]/20 disabled:bg-[var(--disabled)]'
export function Label({
  className,
  ...props
}: React.LabelHTMLAttributes<HTMLLabelElement>) {
  return (
    <label
      className={cn(
        'mb-1 block text-sm font-medium text-[var(--text-primary)]',
        className,
      )}
      {...props}
    />
  )
}
export function FormHint({
  className,
  ...props
}: React.HTMLAttributes<HTMLParagraphElement>) {
  return (
    <p
      className={cn('mt-1 text-xs text-[var(--text-secondary)]', className)}
      {...props}
    />
  )
}
export function FormError({
  className,
  ...props
}: React.HTMLAttributes<HTMLParagraphElement>) {
  return (
    <p
      role="alert"
      className={cn('mt-1 text-xs text-[var(--danger)]', className)}
      {...props}
    />
  )
}
export function Input({
  className,
  error,
  ...props
}: InputHTMLAttributes<HTMLInputElement> & { error?: boolean }) {
  return (
    <input
      className={cn(fieldStyles, error && 'border-[var(--danger)]', className)}
      aria-invalid={error || undefined}
      {...props}
    />
  )
}
export function Textarea({
  className,
  error,
  ...props
}: TextareaHTMLAttributes<HTMLTextAreaElement> & { error?: boolean }) {
  return (
    <textarea
      className={cn(fieldStyles, error && 'border-[var(--danger)]', className)}
      aria-invalid={error || undefined}
      {...props}
    />
  )
}
export function Select({
  className,
  error,
  ...props
}: SelectHTMLAttributes<HTMLSelectElement> & { error?: boolean }) {
  return (
    <select
      className={cn(fieldStyles, error && 'border-[var(--danger)]', className)}
      aria-invalid={error || undefined}
      {...props}
    />
  )
}
export function Checkbox(props: InputHTMLAttributes<HTMLInputElement>) {
  return (
    <input
      type="checkbox"
      className="size-4 accent-[var(--primary)]"
      {...props}
    />
  )
}
export function Radio(props: InputHTMLAttributes<HTMLInputElement>) {
  return (
    <input type="radio" className="size-4 accent-[var(--primary)]" {...props} />
  )
}
export function PasswordInput({
  className,
  ...props
}: InputHTMLAttributes<HTMLInputElement>) {
  const [visible, setVisible] = useState(false)
  return (
    <div className="relative">
      <Input
        type={visible ? 'text' : 'password'}
        className={cn('pr-10', className)}
        {...props}
      />
      <IconButton
        type="button"
        label={visible ? 'Hide password' : 'Show password'}
        className="absolute right-1 top-1"
        onClick={() => setVisible(!visible)}
      >
        {visible ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
      </IconButton>
    </div>
  )
}
export function FormField({
  label,
  hint,
  error,
  children,
}: {
  label: string
  hint?: string
  error?: string
  children: React.ReactElement<{ id?: string; 'aria-describedby'?: string }>
}) {
  const id = useId()
  const describedBy =
    [hint && `${id}-hint`, error && `${id}-error`].filter(Boolean).join(' ') ||
    undefined
  return (
    <div>
      <Label htmlFor={id}>{label}</Label>
      {React.cloneElement(children, {
        id,
        'aria-describedby': describedBy,
        error: Boolean(error),
      } as never)}
      {hint && <FormHint id={`${id}-hint`}>{hint}</FormHint>}
      {error && <FormError id={`${id}-error`}>{error}</FormError>}
    </div>
  )
}
export function SearchInput({
  className,
  ...props
}: InputHTMLAttributes<HTMLInputElement>) {
  return (
    <div className="relative">
      <Search
        aria-hidden="true"
        className="absolute left-3 top-2.5 size-4 text-[var(--text-secondary)]"
      />
      <Input type="search" className={cn('pl-9', className)} {...props} />
    </div>
  )
}
export function PasswordStrength({ value }: { value: string }) {
  const score =
    value.length >= 12 ? 100 : value.length >= 8 ? 66 : value.length ? 33 : 0
  return (
    <div aria-label="Password strength">
      <div className="h-1.5 rounded bg-[var(--surface-muted)]">
        <div
          className="h-full rounded bg-[var(--primary)]"
          style={{ width: `${score}%` }}
        />
      </div>
    </div>
